// Meta Conversions API — Evento Lead
// Executado após captura de lead no webhook

const crypto = require('crypto');

// ── Config ──────────────────────────────────────────────────────────────────
const PIXEL_ID     = $env.META_PIXEL_ID     || '';
const ACCESS_TOKEN = $env.META_CAPI_TOKEN   || '';
const API_VERSION  = 'v20.0';

if (!PIXEL_ID || !ACCESS_TOKEN) {
  throw new Error('META_PIXEL_ID ou META_CAPI_TOKEN não configurados nas env vars do n8n');
}

// ── Dados do lead vindos do webhook ────────────────────────────────────────
const item  = $input.first().json;
const nome  = item.nome  || '';
const fone  = item.telefone || '';
const serv  = item.servico   || '';
const url   = item.origem    || 'https://smartops-ia.com.br';
const eventId = item.event_id || ('capi_lead_' + Date.now()); // para deduplicação

// ── Hash SHA-256 normalizado (exigência da Meta) ────────────────────────────
function h(v) {
  if (!v) return undefined;
  return crypto.createHash('sha256').update(v.trim().toLowerCase()).digest('hex');
}

function normPhone(p) {
  const d = (p || '').replace(/\D/g, '');
  return d.startsWith('55') ? d : '55' + d;
}

// ── Montar nomes (tenta split no campo nome) ────────────────────────────────
const partes = nome.trim().split(/\s+/);
const fn = partes[0] || '';
const ln = partes.slice(1).join(' ') || '';

// ── user_data ───────────────────────────────────────────────────────────────
const userData = {
  fn: h(fn),
  ln: h(ln) || undefined,
  ph: h(normPhone(fone)),
  ct: h('belo horizonte'),   // cidade fixa — ajuste se tiver campo cidade
  st: h('mg'),
  country: h('br'),
  // fbp e fbc: passar se disponíveis nos cookies enviados pelo webhook
  // fbp: item.fbp || undefined,
  // fbc: item.fbc || undefined,
};

// Remove chaves undefined
Object.keys(userData).forEach(k => userData[k] === undefined && delete userData[k]);

// ── Payload CAPI ─────────────────────────────────────────────────────────────
const payload = {
  data: [{
    event_name: 'Lead',
    event_time: Math.floor(Date.now() / 1000),
    event_id: eventId,
    event_source_url: url,
    action_source: 'website',
    user_data: userData,
    custom_data: {
      content_name: serv || 'diagnostico_gratuito',
      content_category: 'consultoria_lean_ia',
    },
  }],
  // test_event_code: 'TEST12345',  // descomente para testar no Events Manager
};

// ── Enviar para Meta CAPI ────────────────────────────────────────────────────
const endpoint = `https://graph.facebook.com/${API_VERSION}/${PIXEL_ID}/events?access_token=${ACCESS_TOKEN}`;

const response = await fetch(endpoint, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(payload),
});

const result = await response.json();

if (!response.ok) {
  console.error('CAPI Error:', JSON.stringify(result));
  throw new Error(`Meta CAPI falhou: ${response.status}`);
}

console.log('CAPI Lead enviado:', result.events_received, 'eventos recebidos');

return [{ json: { capi_status: 'ok', events_received: result.events_received, event_id: eventId } }];
